<header class="properties-page-header"><div><h1>Quadro de <?= $e($config['title']) ?></h1><p>Arraste os cartões entre colunas ou use o seletor para movê-los.</p></div><div class="properties-page-actions"><a role="button" class="outline secondary" href="/<?= $e($type) ?>">Ver lista</a><?php if ($type !== 'properties'): ?><a role="button" class="outline secondary" href="/contacts/invalid">Contatos inválidos</a><?php endif ?></div></header>
<form class="kanban-search" method="get"><label>Buscar no quadro<input type="search" name="q" value="<?= $e($q) ?>" placeholder="Nome, telefone, código ou endereço"></label><button>Buscar</button><?php if($q!==''): ?><a href="/kanban/<?= $e($type) ?>">Limpar</a><?php endif ?></form>
<?php if($type==='leads'): ?><p>As movimentações seguem as regras do funil. Para marcar como perdido, informe o motivo.</p><?php elseif($type==='owners'): ?><p>O envio confirmado no WhatsApp move o proprietário para Contatado.</p><?php endif ?>
<div class="kanban-board" aria-label="Colunas do quadro">
<?php foreach($config['columns'] as $key=>$label): $cards=array_values(array_filter($items,static fn($item)=>$item[$config['field']]===$key)); ?>
<section class="kanban-column" data-stage="<?= $e($key) ?>"><h2><?= $e($label) ?> <span><?= count($cards) ?></span></h2><div class="kanban-cards">
<?php foreach($cards as $item): $id=(int)$item['id']; ?><article class="kanban-card" draggable="true">
<a href="/<?= $e($type) ?>/<?= $id ?>"><strong><?= $e($type==='properties' ? $item['code'].' — '.$item['title'] : $item['name']) ?></strong></a>
<p><?= $e($type==='properties' ? (implode(', ',array_filter([$item['neighborhood'],$item['city']])) ?: 'Localização não informada') : ($item['phone'] ?: ($item['email'] ?: 'Sem contato cadastrado'))) ?></p>
<?php if($type!=='properties' && $item['invalid_contact']): ?><span class="kanban-invalid">Contato inválido</span><?php endif ?>
<form method="post" action="/kanban/<?= $e($type) ?>/<?= $id ?>" class="kanban-move"><?= $csrfField ?><label> Mover para <select name="stage" aria-label="Mover <?= $e($type==='properties'?$item['code']:$item['name']) ?>"><?php foreach($config['columns'] as $option=>$text): ?><?php if($option!==$key && ($type!=='leads' || \App\Modules\Leads\Pipeline\PipelineManager::canTransition($key,$option))): ?><option value="<?= $e($option) ?>"><?= $e($text) ?></option><?php endif ?><?php endforeach ?></select></label><?php if($type==='leads'): ?><label class="kanban-loss" hidden>Motivo da perda<input name="loss_reason" minlength="3" maxlength="4000"></label><?php endif ?><button type="submit" class="outline secondary">Mover</button></form>
<?php if($type!=='properties'): ?><form method="post" action="/contacts/<?= $e($type) ?>/<?= $id ?>/invalid" class="kanban-label-form"><?= $csrfField ?><input type="hidden" name="return_to" value="/kanban/<?= $e($type) ?>"><input type="hidden" name="invalid_contact" value="<?= $item['invalid_contact']?'0':'1' ?>"><button type="submit" class="outline secondary"><?= $item['invalid_contact']?'Remover rótulo':'Marcar contato inválido' ?></button></form><?php endif ?>
</article><?php endforeach ?><?php if(!$cards): ?><p class="kanban-empty">Nenhum cartão nesta coluna.</p><?php endif ?></div></section><?php endforeach ?></div>
<script src="/assets/js/kanban.js?v=<?= (int) filemtime(__DIR__ . '/../../public/assets/js/kanban.js') ?>" defer></script>
